-- Tabla auxiliar de pronósticos (P001-P072)
DROP TABLE IF EXISTS pronosticos_aux;
CREATE TABLE pronosticos_aux (
    id              SERIAL PRIMARY KEY,
    id_partido      VARCHAR(10)  NOT NULL,
    nombre          VARCHAR(200) NOT NULL,
    alias           VARCHAR(100),
    equipo_local    VARCHAR(100),
    goles_local     INTEGER,
    goles_visitante INTEGER,
    equipo_visitante VARCHAR(100),
    amarillas       INTEGER,
    rojas           INTEGER,
    var             INTEGER,
    penales         INTEGER,
    primer_gol      INTEGER
);

CREATE INDEX idx_paux_partido ON pronosticos_aux(id_partido);
CREATE INDEX idx_paux_nombre  ON pronosticos_aux(nombre);

